-- F01-F07 quizzes: bronze/silver/gold, 3 tiers x 7 modules = 21 quizzes

INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'bronze', 'Team Roles & KPI Basics', 'أساسيات أدوار الفريق ومؤشرات الأداء', 80 FROM public.modules WHERE slug = 'finix-team-roles-kpi-evaluation';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'How many core team roles does the Finix smart-home team structure define?', 'كم عدد أدوار الفريق الأساسية التي يحددها هيكل فريق Finix للمنزل الذكي؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-team-roles-kpi-evaluation' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('4', '4', true, 1), ('2', '2', false, 2), ('6', '6', false, 3), ('10', '10', false, 4)) AS v(opt, opt_ar, correct, pos);
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'KPI evaluation for technicians combines technical execution with what other category?', 'يجمع تقييم الأداء (KPI) للفنيين التنفيذ الفني مع أي فئة أخرى؟', 2 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-team-roles-kpi-evaluation' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Behavioral criteria', 'معايير سلوكية', true, 1), ('Sales revenue', 'إيرادات المبيعات', false, 2), ('Social media activity', 'نشاط وسائل التواصل', false, 3), ('Vehicle mileage', 'مسافة السيارة', false, 4)) AS v(opt, opt_ar, correct, pos);
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'What is the typical weighting split between technical execution and behavioral criteria in the KPI framework?', 'ما التوزيع النموذجي للأوزان بين التنفيذ الفني والمعايير السلوكية في إطار KPI؟', 3 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-team-roles-kpi-evaluation' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('60% technical / 40% behavioral', '60٪ فني / 40٪ سلوكي', true, 1), ('50% / 50%', '50٪ / 50٪', false, 2), ('100% technical only', '100٪ فني فقط', false, 3), ('20% technical / 80% behavioral', '20٪ فني / 80٪ سلوكي', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'silver', 'Applying the KPI Framework', 'تطبيق إطار مؤشرات الأداء', 80 FROM public.modules WHERE slug = 'finix-team-roles-kpi-evaluation';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'A technician completes jobs on time but is frequently rude to clients. Which KPI category takes the hit?', 'فني ينهي المهام في الوقت المحدد لكنه فظ مع العملاء باستمرار. أي فئة KPI تتأثر؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-team-roles-kpi-evaluation' AND quizzes.tier = 'silver' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Behavioral criteria', 'المعايير السلوكية', true, 1), ('Technical execution', 'التنفيذ الفني', false, 2), ('Neither', 'لا شيء منهما', false, 3), ('Both equally regardless of behavior', 'كلاهما بالتساوي بغض النظر', false, 4)) AS v(opt, opt_ar, correct, pos);
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'Why does a KPI framework include both technical and behavioral scoring rather than technical alone?', 'لماذا يتضمن إطار KPI تقييمًا فنيًا وسلوكيًا معًا لا فنيًا فقط؟', 2 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-team-roles-kpi-evaluation' AND quizzes.tier = 'silver' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Because client experience depends on conduct as much as correct work', 'لأن تجربة العميل تعتمد على السلوك بقدر العمل الصحيح', true, 1), ('Behavioral scoring is legally required', 'التقييم السلوكي مطلوب قانونيًا', false, 2), ('Technical scoring is unreliable', 'التقييم الفني غير موثوق', false, 3), ('It has no real purpose', 'لا غرض حقيقي له', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'gold', 'Team Structure & Performance Strategy', 'استراتيجية هيكل الفريق والأداء', 80 FROM public.modules WHERE slug = 'finix-team-roles-kpi-evaluation';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'As a team lead reviewing consistently low behavioral scores across multiple technicians, what''s the most appropriate first response?', 'كقائد فريق يراجع درجات سلوكية منخفضة باستمرار لعدة فنيين، ما الاستجابة الأولى الأنسب؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-team-roles-kpi-evaluation' AND quizzes.tier = 'gold' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Investigate whether it''s a training gap or a systemic issue before individual discipline', 'التحقق إن كانت فجوة تدريبية أو مشكلة نظامية قبل الانضباط الفردي', true, 1), ('Immediately terminate all affected technicians', 'إنهاء خدمة كل الفنيين المتأثرين فورًا', false, 2), ('Ignore it since technical scores matter more', 'تجاهلها لأن الدرجات الفنية أهم', false, 3), ('Remove behavioral scoring from the KPI framework', 'إزالة التقييم السلوكي من إطار KPI', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'bronze', 'Electrical Fundamentals Basics', 'أساسيات الكهرباء', 80 FROM public.modules WHERE slug = 'finix-electrical-fundamentals-deep-dive';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'What is the key difference between DC and AC current?', 'ما الفرق الأساسي بين التيار المستمر والمتردد؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-electrical-fundamentals-deep-dive' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('DC flows in one direction, AC periodically reverses direction', 'المستمر يتدفق باتجاه واحد، المتردد يعكس اتجاهه دوريًا', true, 1), ('DC is always higher voltage than AC', 'المستمر دائمًا أعلى جهدًا من المتردد', false, 2), ('AC only exists in batteries', 'المتردد موجود فقط في البطاريات', false, 3), ('There is no real difference', 'لا فرق حقيقي بينهما', false, 4)) AS v(opt, opt_ar, correct, pos);
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'Ohm''s Law relates which three quantities?', 'قانون أوم يربط بين أي ثلاث كميات؟', 2 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-electrical-fundamentals-deep-dive' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Voltage, current, resistance', 'الجهد والتيار والمقاومة', true, 1), ('Power, frequency, phase', 'القدرة والتردد والطور', false, 2), ('Voltage, humidity, temperature', 'الجهد والرطوبة والحرارة', false, 3), ('Current, distance, time', 'التيار والمسافة والزمن', false, 4)) AS v(opt, opt_ar, correct, pos);
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'Three-phase power distribution commonly uses which two connection configurations?', 'توزيع الطاقة الثلاثية الأطوار يستخدم غالبًا أي تكوينين للتوصيل؟', 3 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-electrical-fundamentals-deep-dive' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Star (Y) and Delta', 'نجمة (Y) ودلتا', true, 1), ('Circle and Square', 'دائرة ومربع', false, 2), ('Series and Parallel only', 'التوالي والتوازي فقط', false, 3), ('Linear and Radial', 'خطي وشعاعي', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'silver', 'Applying Cable Sizing & Load Calculations', 'تطبيق حساب أقطار الكابلات والأحمال', 80 FROM public.modules WHERE slug = 'finix-electrical-fundamentals-deep-dive';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'Why is cable current-carrying capacity selected based on the breaker''s rated current rather than the raw load current?', 'لماذا تُختار سعة تحمل الكابل بناءً على تيار القاطع المقنن لا تيار الحمل الخام؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-electrical-fundamentals-deep-dive' AND quizzes.tier = 'silver' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Because the breaker''s job is to protect the cable, so the cable must handle at least the breaker''s rating', 'لأن وظيفة القاطع حماية الكابل، فيجب أن يتحمل الكابل تيار القاطع على الأقل', true, 1), ('Load current is always higher than breaker rating', 'تيار الحمل دائمًا أعلى من تيار القاطع', false, 2), ('It''s arbitrary convention with no technical reason', 'مجرد عرف تعسفي بلا سبب تقني', false, 3), ('Cable capacity is unrelated to breaker rating', 'سعة الكابل لا علاقة لها بتيار القاطع', false, 4)) AS v(opt, opt_ar, correct, pos);
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'A load calculation shows a device drawing 8A. What breaker rating margin should be applied for safety?', 'حساب حمل يُظهر جهازًا يسحب 8 أمبير. ما هامش تصنيف القاطع الذي يجب تطبيقه للأمان؟', 2 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-electrical-fundamentals-deep-dive' AND quizzes.tier = 'silver' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Roughly 25% above the load current', 'نحو 25٪ فوق تيار الحمل', true, 1), ('Exactly equal to the load current', 'مساويًا تمامًا لتيار الحمل', false, 2), ('50% below the load current', 'أقل 50٪ من تيار الحمل', false, 3), ('There''s no standard margin', 'لا يوجد هامش قياسي', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'gold', 'Three-Phase Power & Advanced Troubleshooting', 'الطاقة الثلاثية الأطوار واستكشاف الأعطال المتقدم', 80 FROM public.modules WHERE slug = 'finix-electrical-fundamentals-deep-dive';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'A commercial site''s three-phase panel shows imbalanced loading across phases. What is the most likely consequence if left unaddressed?', 'لوحة ثلاثية الأطوار في موقع تجاري تُظهر أحمالًا غير متوازنة عبر الأطوار. ما النتيجة الأكثر احتمالًا إذا تُرِكت دون معالجة؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-electrical-fundamentals-deep-dive' AND quizzes.tier = 'gold' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Uneven heating and reduced equipment lifespan, particularly for motors', 'تسخين غير متساوٍ وتقليل عمر المعدات، خاصة المحركات', true, 1), ('No practical effect at all', 'لا تأثير عملي على الإطلاق', false, 2), ('The system will automatically self-balance', 'سيتوازن النظام تلقائيًا', false, 3), ('It only affects the electricity bill, nothing else', 'يؤثر فقط على فاتورة الكهرباء، لا شيء آخر', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'bronze', 'Site Survey Basics', 'أساسيات المعاينة الميدانية', 80 FROM public.modules WHERE slug = 'finix-site-survey-methodology';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'What is the primary purpose of a site survey before a smart home installation?', 'ما الغرض الأساسي من المعاينة الميدانية قبل تركيب المنزل الذكي؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-site-survey-methodology' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('To gather accurate site data so the design and quote match reality', 'جمع بيانات دقيقة عن الموقع ليطابق التصميم والتسعير الواقع', true, 1), ('To sell additional unrelated products', 'بيع منتجات إضافية غير ذات صلة', false, 2), ('It has no real purpose beyond formality', 'لا غرض حقيقي له سوى الشكليات', false, 3), ('To skip the design phase entirely', 'لتخطي مرحلة التصميم بالكامل', false, 4)) AS v(opt, opt_ar, correct, pos);
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'A standardized survey form typically covers which categories?', 'استمارة المعاينة الموحدة تغطي عادة أي فئات؟', 2 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-site-survey-methodology' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Rooms, device counts, entrances, outdoor areas, security/safety', 'الغرف، عدد الأجهزة، المداخل، المناطق الخارجية، الأمن والسلامة', true, 1), ('Only the client''s budget', 'ميزانية العميل فقط', false, 2), ('Only paint colors', 'ألوان الطلاء فقط', false, 3), ('Only the client''s work schedule', 'جدول عمل العميل فقط', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'silver', 'Conducting a Thorough Survey', 'إجراء معاينة شاملة', 80 FROM public.modules WHERE slug = 'finix-site-survey-methodology';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'Why should a site survey capture per-room device counts rather than just a single total for the whole property?', 'لماذا يجب أن تسجل المعاينة عدد الأجهزة لكل غرفة لا إجماليًا واحدًا للعقار بأكمله؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-site-survey-methodology' AND quizzes.tier = 'silver' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Wiring runs and switch/relay placement are room-specific, so per-room detail drives accurate design', 'مسارات الأسلاك ومواقع المفاتيح والريليهات خاصة بكل غرفة، فالتفاصيل لكل غرفة تقود لتصميم دقيق', true, 1), ('It makes no practical difference', 'لا فرق عمليًا', false, 2), ('Totals are always more accurate than per-room detail', 'الإجماليات دائمًا أدق من التفاصيل لكل غرفة', false, 3), ('Per-room detail is only needed for very large homes', 'التفاصيل لكل غرفة مطلوبة فقط للمنازل الكبيرة جدًا', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'gold', 'Survey-Driven Design Decisions', 'قرارات تصميم مبنية على المعاينة', 80 FROM public.modules WHERE slug = 'finix-site-survey-methodology';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'During a survey you find the client''s Wi-Fi router is in a corner far from most rooms needing devices. What should this drive in your proposal?', 'أثناء المعاينة تجد راوتر واي فاي العميل في زاوية بعيدة عن أغلب الغرف التي تحتاج أجهزة. ماذا يجب أن يقود هذا في مقترحك؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-site-survey-methodology' AND quizzes.tier = 'gold' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('Recommending mesh access points or protocol choices (e.g. Zigbee routers) that don''t depend solely on router placement', 'التوصية بنقاط وصول شبكية أو اختيار بروتوكولات (مثل راوترات Zigbee) لا تعتمد فقط على موقع الراوتر', true, 1), ('Ignoring the issue since it''s the client''s problem', 'تجاهل المشكلة لأنها مشكلة العميل', false, 2), ('Proceeding with the original plan unchanged', 'المتابعة بالخطة الأصلية دون تغيير', false, 3), ('Canceling the project entirely', 'إلغاء المشروع بالكامل', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'bronze', 'Power Devices & Breakers Basics', 'أساسيات أجهزة الطاقة والقواطع', 80 FROM public.modules WHERE slug = 'finix-power-devices-protection';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'What distinguishes a charger from a simple adapter?', 'ما الذي يميز الشاحن عن الأدابتور البسيط؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-power-devices-protection' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('A charger manages the charging process dynamically with a smart cutoff', 'الشاحن يدير عملية الشحن ديناميكيًا بقطع ذكي', true, 1), ('There is no difference', 'لا فرق بينهما', false, 2), ('An adapter always costs more', 'الأدابتور دائمًا أغلى ثمنًا', false, 3), ('A charger never converts AC to DC', 'الشاحن لا يحوّل أبدًا من متردد إلى مستمر', false, 4)) AS v(opt, opt_ar, correct, pos);
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'Which circuit breaker type is typically used for home lighting and outlet circuits?', 'أي نوع قاطع يُستخدم عادة لدوائر الإضاءة والمقابس المنزلية؟', 2 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-power-devices-protection' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('MCB', 'MCB', true, 1), ('ACB', 'ACB', false, 2), ('MCCB with 4th pole only', 'MCCB بالقطب الرابع فقط', false, 3), ('None — breakers aren''t used in homes', 'لا شيء — لا تُستخدم القواطع بالمنازل', false, 4)) AS v(opt, opt_ar, correct, pos);
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'What does NO (Normally Open) mean for a relay contact?', 'ماذا يعني NO (عادة مفتوح) لنقطة تلامس الريليه؟', 3 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-power-devices-protection' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('The circuit is open until the relay is energized', 'الدارة مفتوحة حتى يُنشَّط الريليه', true, 1), ('The circuit is always closed', 'الدارة مغلقة دائمًا', false, 2), ('It refers to the relay''s coil voltage', 'يشير إلى جهد ملف الريليه', false, 3), ('It has no functional meaning', 'لا معنى وظيفيًا له', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'silver', 'Selecting Protection Devices', 'اختيار أجهزة الحماية', 80 FROM public.modules WHERE slug = 'finix-power-devices-protection';
