WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'What is the relay output rating per channel on the Alpha Core?', 'ما تصنيف إخراج الريليه لكل قناة في Alpha Core؟', 3 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-alpha-control-platform' AND quizzes.tier = 'bronze' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('10A @ 250V AC', '10 أمبير عند 250 فولت متردد', true, 1), ('50A @ 250V AC', '50 أمبير عند 250 فولت متردد', false, 2), ('1A @ 12V DC', '1 أمبير عند 12 فولت مستمر', false, 3), ('100A @ 250V AC', '100 أمبير عند 250 فولت متردد', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'silver', 'Choosing Expansion Modules', 'اختيار وحدات التوسعة', 80 FROM public.modules WHERE slug = 'finix-alpha-control-platform';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'A job requires controlling an EV charger. Which Alpha Control expansion module is mandatory?', 'مشروع يتطلب التحكم بشاحن سيارة كهربائية. أي وحدة توسعة إلزامية لـAlpha Control؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-alpha-control-platform' AND quizzes.tier = 'silver' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('High-Current Module (50A per channel)', 'وحدة التيار العالي (50 أمبير لكل قناة)', true, 1), ('Sound System Module', 'وحدة نظام الصوت', false, 2), ('Interlock Module alone is sufficient', 'وحدة القفل التبادلي وحدها كافية', false, 3), ('No module is needed, the core''s standard channels are sufficient', 'لا حاجة لوحدة، قنوات الكور القياسية كافية', false, 4)) AS v(opt, opt_ar, correct, pos);
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'Why is the Interlock Module''s hardware-level protection more robust than a pure software rule?', 'لماذا تُعد حماية وحدة القفل التبادلي على مستوى العتاد أكثر متانة من قاعدة برمجية بحتة؟', 2 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-alpha-control-platform' AND quizzes.tier = 'silver' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('It continues enforcing the interlock even during a firmware fault or network outage', 'تستمر بفرض القفل التبادلي حتى أثناء عطل البرنامج الثابت أو انقطاع الشبكة', true, 1), ('Hardware protection is always cheaper', 'الحماية العتادية دائمًا أرخص', false, 2), ('There is no meaningful difference', 'لا فرق ذو معنى', false, 3), ('Software rules are always more reliable', 'القواعد البرمجية دائمًا أكثر موثوقية', false, 4)) AS v(opt, opt_ar, correct, pos);
INSERT INTO public.quizzes (module_id, tier, title, title_ar, pass_percent) SELECT id, 'gold', 'Full System Design with Alpha Control', 'تصميم نظام كامل باستخدام Alpha Control', 80 FROM public.modules WHERE slug = 'finix-alpha-control-platform';
WITH q AS (INSERT INTO public.quiz_questions (quiz_id, question, question_ar, position) SELECT quizzes.id, 'A factory floor needs 3 high-draw conveyor motors, a 4-zone paging system, and a safety rule preventing two specific motors from running simultaneously. How many expansion modules are needed and which?', 'طابق مصنع يحتاج 3 محركات سيور عالية السحب، ونظام نداء بـ4 مناطق، وقاعدة سلامة تمنع تشغيل محركين معينين معًا. كم عدد وحدات التوسعة المطلوبة وأيها؟', 1 FROM public.quizzes JOIN public.modules ON modules.id = quizzes.module_id WHERE modules.slug = 'finix-alpha-control-platform' AND quizzes.tier = 'gold' RETURNING id) INSERT INTO public.quiz_options (question_id, option_text, option_text_ar, is_correct, position) SELECT q.id, v.opt, v.opt_ar, v.correct, v.pos FROM q, (VALUES ('All 3: High-Current, Sound System, and Interlock', 'الثلاث جميعًا: التيار العالي، نظام الصوت، والقفل التبادلي', true, 1), ('Only the Sound System Module', 'وحدة نظام الصوت فقط', false, 2), ('None, the core alone covers this', 'لا شيء، الكور وحده يغطي هذا', false, 3), ('A fourth custom module not offered by Alpha Control', 'وحدة رابعة مخصصة غير متوفرة من Alpha Control', false, 4)) AS v(opt, opt_ar, correct, pos);
